package com.wizzadrds.theworldremembers.voice; import java.io.*; import java.nio.file.*; public final class ProcessTextToSpeechAdapter implements TextToSpeechAdapter { private final Path executable; public ProcessTextToSpeechAdapter(Path executable){this.executable=executable;} public Path synthesize(String text,VoiceProfile profile,Path output)throws IOException,InterruptedException{if(text==null||text.isBlank())throw new IllegalArgumentException("text");Path parent=output.toAbsolutePath().getParent();if(parent!=null)Files.createDirectories(parent);Process p=new ProcessBuilder(executable.toString(),text,output.toAbsolutePath().toString(),profile.model(),profile.language()).redirectErrorStream(true).start();String log=new String(p.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);int code=p.waitFor();if(code!=0)throw new IOException("Local TTS exited with "+code+": "+log);if(!Files.isRegularFile(output))throw new IOException("TTS produced no output");return output;} }
